  breakdown?:
    | null
    | {
        comment?: null | string
        criterion: string
        /**
         * a decimal number; a string is accepted where exactness matters, with at most 40 digits either side of the point and an exponent of at most two digits
         */
        max: number | string
        /**
         * a decimal number; a string is accepted where exactness matters, with at most 40 digits either side of the point and an exponent of at most two digits
         */
        points: number | string
      }[]
  /**
   * the course this call is about
   */
